CREATE TABLE result AS WITH RECURSIVE q(ii) AS (SELECT 1 UNION ALL SELECT ii+1 FROM q WHERE ii<9999) SELECT q.ii AS request,1 AS source,v1.rowid AS rid,v1.i AS i,v1.t AS txt FROM q JOIN v1 ON v1.rowid=q.ii*3 WHERE (q.ii%3)+1=1 UNION ALL SELECT q.ii,2,v2.rowid,v2.i,v2.t FROM q JOIN v2 ON v2.rowid=q.ii*3 WHERE (q.ii%3)+1=2 UNION ALL SELECT q.ii,3,v3.rowid,v3.i,v3.t FROM q JOIN v3 ON v3.rowid=q.ii*3 WHERE (q.ii%3)+1=3;